Status record_personal_appointment_zero_time_in_candidate(PersonalAppointmentState&s,const PersonalAppointmentTime2Context&x,const SourceRef&r){return guard<Done>([&]{selected(x);if(&s!=&x.state)reject("PersonalAppointmentCandidateMismatch");const auto t=table(r.domain,r.kind,r.id);if(t!=S3PersonalAppointmentTable::accepted&&t!=S3PersonalAppointmentTable::cancelled)reject("PersonalAppointmentZeroStepKindMismatch",r.id);position(x.common,r);insert(s,t,r.id,take(x.clock.read_current_moment()),S3CommittedZeroStepSourceBuildView{{},{r.domain,r.kind,r.id}});return Done{};});}
Status bind_personal_appointment_time2_command_result(CommonStore&c,PersonalAppointmentState&s,const PersonalAppointmentTime2Context&x,const std::vector<StableId>&sources,const CommitResult&commit){return guard<Done>([&]{selected(x);if(&c!=&x.common||&s!=&x.state)reject("PersonalAppointmentCandidateMismatch");auto original=take(read_common_command_source(c,std::string_view(commit.result_id)));if(original.result!=&commit)reject("PersonalAppointmentActualCommitRequired");for(const auto&id:sources){const auto*h=c.state().facts.find(id);if(!h||h->domain!=personal_appointment_module)reject("PersonalAppointmentNewSourceMissing",id);const auto t=table(h->domain,h->kind,id);if(t==S3PersonalAppointmentTable::accepted||t==S3PersonalAppointmentTable::cancelled){const auto key=S3EventTimeKey(t,id,role(t));auto*e=s.temporal_events.find(key.value());auto*at=e?std::get_if<S3ExactEventMoment>(&e->precision):nullptr;auto*pending=at?std::get_if<S3CommittedZeroStepSource>(&at->actual_source):nullptr;if(!pending||!pending->original_commit_result_ref.id.empty()||!pending->original_commit_result_ref.domain.empty()||!pending->original_commit_result_ref.kind.empty()||(pending->actual_contact_source_ref.domain!=personal_appointment_module||pending->actual_contact_source_ref.kind!=kind(t)||pending->actual_contact_source_ref.id!=id)||take(compare_world_moments(at->occurred_at,take(x.clock.read_current_moment()))))reject("PersonalAppointmentActualPendingZeroRequired",id);// Rebuild under the original finite input owner before replacing the
 // actual table row. Old/new fields coexist with distinct real charges.
 auto replacement=borrow_s3_event_time(*e);
 auto&exact=std::get<S3ExactEventMomentBuildView>(replacement.precision);
 std::get<S3CommittedZeroStepSourceBuildView>(exact.actual_source).original_commit_result_ref={"common","command_result",commit.result_id};
 const S3EventTimeInput owned(replacement);s.temporal_events.set(key.value(),owned.row());}read(x,t,id);}return Done{};});}
Status record_personal_appointment_started_time_in_candidate(CommonStore&c,PersonalAppointmentState&s,ActionElapsedStore&elapsed,const PersonalAppointmentTime2Context&x,const StableId&id){return guard<Done>([&]{selected(x);if(&c!=&x.common||&s!=&x.state||&elapsed!=&x.elapsed)reject("PersonalAppointmentCandidateMismatch");const auto*begun=s.started.find(id);const auto*action=begun?c.action(begun->action_id):nullptr;if(!begun||!action)reject("PersonalAppointmentActualStartRequired",id);const auto&a=accepted(x,begun->appointment_id);const auto at=take(x.clock.read_current_moment());insert(s,S3PersonalAppointmentTable::started,id,at,S3ActionStartedSourceBuildView{action->id,{personal_appointment_module,personal_appointment_started_kind,id}});const S3ServiceDurationRuleInput duration_rule(a.policy_id);auto entry=take(begin_fixed_elapsed(action->id,id,duration_rule.value(),id,at,a.duration_ticks,x.scale));const FixedServiceAdoptionInputs original_inputs({personal_appointment_module,personal_appointment_started_kind,id},2,x.identity,duration_rule.value());
 const auto transition_id=take(c.next_owned_id("fixed_service_transition"));
 const std::vector<FixedServiceInputRef> no_inputs;
 FixedServiceTransitionInput owned{FixedServiceAdoptionTransitionBuildView{
  transition_id.id(),1,action->id,0,std::nullopt,FixedTransitionKind::started,at,entry.credited_units,
  {personal_appointment_module,personal_appointment_started_kind,id},2,
  {{personal_appointment_module,personal_appointment_started_kind,id},2},original_inputs.values(),no_inputs,std::nullopt}};
 const auto&transition=owned.row();PersonalAppointmentActionTimeRead reader(x);auto reg=personal_appointment_action_time_registration();auto prepared=take(prepare_fixed_service_adoption(*action,entry,transition,reg,x.scale,reader));take(apply_fixed_service_change_in_candidate(elapsed,std::move(prepared),reg,x.scale,reader));return Done{};});}
Status record_personal_appointment_finished_time_in_candidate(CommonStore&c,PersonalAppointmentState&s,ActionElapsedStore&elapsed,const PersonalAppointmentTime2Context&x,const StableId&id,const std::optional<DeathRef>&death){return guard<Done>([&]{selected(x);if(&c!=&x.common||&s!=&x.state||&elapsed!=&x.elapsed)reject("PersonalAppointmentCandidateMismatch");const auto*f=s.finished.find(id);const auto*begun=f?s.started.find(f->start_fact_id):nullptr;const auto*entry=begun?find_fixed_elapsed(elapsed,begun->action_id):nullptr;if(!f||!begun||!entry||!c.action(begun->action_id))reject("PersonalAppointmentActualFinishRequired",id);const auto at=take(x.clock.read_current_moment());S3EventActualSourceBuildView actual=S3ActionFinishedSourceBuildView{begun->action_id,{personal_appointment_module,personal_appointment_finished_kind,id}};if(death)actual=S3ActualTerminationSourceBuildView{{death->domain,death->kind,death->id},SourceRefBuildView{personal_appointment_module,personal_appointment_finished_kind,id}};else take(validate_fixed_elapsed_at_completion_due(*entry,at,x.scale));insert(s,S3PersonalAppointmentTable::finished,id,at,actual);const FixedServiceTransition*prior=nullptr;for(const auto&row:elapsed.fixed_service_transitions)if(row.action_ref==begun->action_id)prior=&row;if(!prior||prior->kind!=FixedTransitionKind::started)reject("PersonalAppointmentStartTransitionMissing",id);WorkUnits credited=entry->credited_units;
 if(take(compare_world_moments(entry->last_settled_at,at))!=0){auto settled=take(prepare_fixed_elapsed_slice(*entry,{entry->last_settled_at,at},x.scale));credited=std::move(settled.credited_units);}
 const auto transition_id=take(c.next_owned_id("fixed_service_transition"));
 const std::vector<FixedServiceInputRef> no_inputs;
 FixedServiceTransitionInput owned{FixedServiceTerminalTransitionBuildView{
  transition_id.id(),1,begun->action_id,1,prior->transition_id,FixedTransitionKind::terminal,at,credited,
  {personal_appointment_module,personal_appointment_started_kind,begun->fact_id},2,
  {{personal_appointment_module,personal_appointment_finished_kind,id},2},no_inputs,prior->input_basis_refs,
  death?FixedTerminalDisposition::interrupted:FixedTerminalDisposition::completed}};
 const auto&transition=owned.row();PersonalAppointmentActionTimeRead reader(x);auto reg=personal_appointment_action_time_registration();auto prepared=take(prepare_fixed_service_change(elapsed,begun->action_id,transition,{},reg,x.scale,reader));take(apply_fixed_service_change_in_candidate(elapsed,std::move(prepared),reg,x.scale,reader));return Done{};});}
